#!/usr/bin/env python3
# PYTHON_ARGCOMPLETE_OK

import os

kconfig_tmpl = """
#
# Automatically generated by gen_panel_config.py; DO NOT EDIT.
#

menu "Panel settings"
{0}

{1}

endmenu
"""

kconfig_choice_tmpl = """
choice
    prompt "{0}"
    default {1}
{2}
endchoice
"""

kconfig_config_bool_tmpl = """
config {0}
    bool "{1}"
    help
      "y" Config {1}.
"""

SCRIPT_DIR = os.path.normpath(os.path.dirname(__file__))
PANEL_HEADER_DIR = os.path.join(SCRIPT_DIR, "panels")
PANEL_KCONFIG_PATH = os.path.join(SCRIPT_DIR, "Kconfig.panels")


def get_panel_headers():
    panel_headers = []

    for entry in os.listdir(PANEL_HEADER_DIR):
        panel_path = os.path.join(PANEL_HEADER_DIR, entry)
        if not os.path.isfile(panel_path):
            continue
        if not entry.endswith(".h") or entry == "panel_platform.h":
            continue
        panel_headers.append(os.path.splitext(entry)[0])

    return sorted(panel_headers)


def gen_panel_list(panel_headers):
    kconfig_panel_list = ""

    for panel in panel_headers:
        kconfig_panel_list = (
            kconfig_panel_list
            + kconfig_config_bool_tmpl.format(panel.upper(), panel))

    kconfig_panel_list = kconfig_choice_tmpl.format(
        "Panel selecting",
        "DSI_HX8394_720X1280_NULL_4LANE_60FPS",
        kconfig_panel_list,
    )

    return kconfig_panel_list


def main():

    panel_headers = get_panel_headers()

    kconfig = kconfig_tmpl.format(
        gen_panel_list(panel_headers), ""
    )

    with open(PANEL_KCONFIG_PATH, "w") as fp:
        fp.write(kconfig)


if __name__ == "__main__":
    main()
